import os
import torch


class Config:
    # ==========================================
    # Experiment & Paths
    # ==========================================
    EXPERIMENT_NAME = "idea_67"
    WORKING_DIR = f"./working/{EXPERIMENT_NAME}"

    # Input Metadata Paths (Generated by metadata script)
    TRAIN_DATA_PATH = "./metadata/train.parquet"
    VAL_DATA_PATH = "./metadata/val.parquet"
    TEST_DATA_PATH = "./metadata/test.parquet"
    SAMPLE_SUBMISSION_PATH = "./input/sample_submission.csv"

    # Output Paths
    MODEL_SAVE_PATH = os.path.join(WORKING_DIR, "best_model.pth")
    SUBMISSION_PATH = os.path.join(WORKING_DIR, "submission.csv")

    # Cache Paths
    TRAIN_CACHE = os.path.join(WORKING_DIR, "train_cache.npy")
    VAL_CACHE = os.path.join(WORKING_DIR, "val_cache.npy")
    TEST_CACHE = os.path.join(WORKING_DIR, "test_cache.npy")

    # ==========================================
    # Data Dimensions
    # ==========================================
    SEQ_LEN = 107
    PRED_LEN = 68

    # Input Channels:
    # 4 (Sequence: A, G, C, U)
    # + 3 (Structure: (, ), .)
    # + 7 (Loop Type: S, M, I, B, H, E, X)
    INPUT_DIM = 14

    # Targets: reactivity, deg_Mg_pH10, deg_pH10, deg_Mg_50C, deg_50C
    NUM_TARGETS = 5

    # Columns used for validation scoring
    SCORING_COLS = ["reactivity", "deg_Mg_pH10", "deg_Mg_50C"]

    # ==========================================
    # Model Architecture (DAD-BiGRU)
    # ==========================================
    # Convolutional Stem
    CONV_KERNEL_SIZE = 3
    CONV_FILTERS = 256

    # RNN Backbone
    HIDDEN_DIM = 384  # BiGRU output will be 2 * 384 = 768
    N_LAYERS = 4
    DROPOUT = 0.1

    # Affine Structural Module
    # These parameters control the internal projections for scale/shift/gate

    # ==========================================
    # Training Hyperparameters
    # ==========================================
    SEED = 2024
    BATCH_SIZE = 64
    EPOCHS = 50
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-4
    MAX_GRAD_NORM = 1.0

    # Scheduler (Cosine Annealing)
    T_MAX = EPOCHS  # For CosineAnnealingLR
    ETA_MIN = 1e-6

    # Early Stopping
    PATIENCE = 10

    # Device
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4

    @classmethod
    def setup(cls):
        """Ensures the working directory exists."""
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        print(f"Configuration loaded. Working directory: {cls.WORKING_DIR}")
        print(f"Device: {cls.DEVICE}")


# Initialize setup immediately when module is imported to ensure directories exist
Config.setup()
